dual influence", "auto_outcome_status": "supported", "observed_hypothesis": "Structural influence is not reducible to usage and the usage-residual is a reproducible player property.", "observed_result": ["[APPA-039] F1a cosine R2=0.094, residual-share=0.906, CI [0.768, 0.962] PASS; Frobenius R2=0.073 share=0.927 CI [0.828, 0.965]. F1b pooled-residual rho=+0.685 p=0.0000 CI [+0.649, +0.721]; usage-partial rho=+0.557 p=0.00 [cut; read_family for the full text]", "[APPS-083] F1a cosine R2=0.099 share=0.901 CI[0.778,0.954]; frobenius R2=0.084 share=0.916. F1b pooled rho=+0.670 p=0.0000 CI[+0.636,+0.705]; partial rho=+0.560 CI[+0.496,+0.616]. F1a=CONFIRMED F1b=CONFIRMED."], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:low_measurement_reliability"}, {"rel": "auto_has_risk", "node": "RISK:MEASURE_RELIABILITY"}]}, {"id": "FAM:SF-PAP-033", "label": "Study family SF-PAP-033: Split-half validation of travel x fit outcome ordering", "score": 0.321, "reached_via": ["request matches the question or hypothesis of FAM:SF-PAP-033 (0.15)", "request matches METH:split_half_reliability (0.32); FAM:SF-PAP-033 auto_uses_method METH:split_half_reliability"], "attributes": {"observed_research_question": "Split-half validation of travel x fit outcome ordering", "auto_outcome_status": "supported", "observed_hypothesis": "Additive > irrelevant on destination embedded minutes and on-court net rating survives when travel OLS and medians are fit on a calibration half and scored on holdout.", "observed_result": "500 splits; embedded-rate gap median=+0.116 [10-90% -0.033, +0.248] P(>0)=0.838; net-rtg gap median=+2.926 [+0.541, +5.072] P(>0)=0.960; corr(travel forecast, net rtg) median=+0.178 P(>0)=0.976; corr(delta, net) median=+ [cut; read_family for the full text]", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "additive>irrelevant on net rating in 96% of holdout splits; minutes gap positive in 84%", "observed_sample_and_power": "n~198 movers, 500 splits, half~99", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-039"}, {"rel": "auto_related_family", "node": "FAM:SF-PAP-032"}]}, {"id": "FAM:SF-APPS-018", "label": "Study family SF-APPS-018: Ranked playsheet validation, 10 series (Spearman null; pairwise BEST>AVOID)", "score": 0.242, "reached_via": ["request matches LIM:low_measurement_reliability (0.27); FAM:SF-APPS-018 auto_limited_by LIM:low_measurement_reliability", "request matches RISK:MEASURE_RELIABILITY (0.18); FAM:SF-APPS-018 auto_has_risk RISK:MEASURE_RELIABILITY"], "attributes": {"observed_research_question": "Ranked playsheet validation, 10 series (Spearman null; pairwise BEST>AVOID)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "When a defense drops a play type >=0.25 PPP H1 to H2, playsheet counter ranking predicts which alternative scored better in H2 (BEST > SECOND > AVOID).", "observed_result": "Spearman rho=-0.0639, p=0.099717, n=665 (no clear full-rank signal). Kruskal-Wallis H=32.9723, p=2.7e-05. Mann-Whitney BEST 1.257 (n=56) vs AVOID 1.092 (n=160), U=5546.0, p=0.004018. Trigger accuracy rho=0.4525, n=121. F [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:leakage"}, {"rel": "auto_limited_by", "node": "LIM:low_measurement_reliability"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}, {"rel": "auto_has_risk", "node": "RISK:LEAKAGE_LOOKAHEAD"}, {"rel": "auto_has_risk", "node": "RISK:MEASURE_RELIABILITY"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}], "n_results": 4}

