  "testability": {
    "p_testable": 0.35,
    "blocking_constraints": [
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "With ~120 team-seasons spanning three full seasons and one partial, year-to-year reliability would be estimated on approximately 90 paired observations (30 teams × 3 seasonal transitions), possibly fewer after roster continuity filters. Detecting a true correlation of 0.3–0.4 would be marginally powered; a more realistic correlation of 0.2 would be severely underpowered."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "Single-game H2-H1 scoring margin is highly noisy. Even after aggregation across 82 games, the team-level metric may exhibit insufficient inter-season reliability, analogous to the untestable split-half trait in SF-APPS-085."
      },
      {
        "code": "CONFOUNDING",
        "text": "Opponent quality, game location, score effects (e.g., garbage time), and team offensive adjustments confound the raw differential. Without a well-validated adjustment model, the trait may reflect the opposing offense's characteristics rather than the defense's halftime adjustment ability."
      }
    ]
  },
  "prior_work": {
    "already_answered": "no",
    "cited": [
      "FAM:SF-APPS-085",
      "FAM:SF18"
    ],
    "summary": "No earlier study directly tested whether a defense's influence on opponents' second-half vs first-half scoring change is a reliable team-level trait. The closest precedents examined split-half reliability of player-level halftime-based metrics (SF-APPS-085, untestable) and split-half stability of structural influence (SF18, supported), but none aggregated to team-season level or addressed year-to-year stability."
  },
  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Year-to-year analysis suffers from limited independent observations (~90 team-season pairs), reducing power to detect plausible correlation sizes."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Game-level H2-H1 is noisy; even after aggregating 82 games, measurement error may be substantial, as seen in SF-APPS-085."
    },
    {
      "code": "CONFOUNDING",
      "text": "Unadjusted differentials mix the defense's effect with opponent offensive strength, home-court advantage, and score effects; controlling for these requires a model whose residual may still retain systematic noise."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Teams with extreme first-half performance (good or bad) may regress toward the mean in the second half, producing spurious correlations if not properly accounted for."
    },
    {
      "code": "DRIFT_NONSTATIONARITY",
      "text": "Coaching, roster, and strategic trends shift over seasons, weakening the assumption that any halftime-adjustment trait would remain stable across years."
    }
  ],
  "predicted_outcome": {
    "supported": 0.15,
    "rejected": 0.25,
    "untestable": 0.35,
    "artifact": 0.05,
    "uncertain": 0.20
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Year-to-year stability of the team-level average opponent second-half-minus-first-half scoring differential, adjusted for opponent offensive efficiency, home/away, and score differential entering the second half. The trait is defined as the random effects team intercept (or shrunken estimate) from a mixed model predicting game-level adjusted H2-H1 differential, correlated between consecutive seasons.",
    "unit": "team-season (a single team's regular-season games)",
    "sample": "NBA 2022-23 through 2024-25 regular seasons (3 full seasons, 90 team-seasons), using the completed 2025-26 regular season if available by analysis date (adding up to 30 more team-seasons). Each team-season contains all games where the team was the defense and the opponent scoring is recorded. After filtering for games with complete play-by-play and >24 minutes of non-garbage time, the expected sample is ~70–80 games per team-season.",
    "power": "With 90 teams-season pairs (for example, correlating 2023 measure with 2024 measure, pooled across all transitions), a two-sided test at α=0.05 can detect a true Pearson correlation of r ≥ 0.35 with ~80% power. A more realistic r = 0.20 would be underpowered (~35% power). Within-season split-half reliability (splitting games 1–41 vs 42–82) yields 120 observations and would detect r ≥ 0.25 with 80% power, but that measures internal consistency rather than seasonal stability.",
    "controls": "Pre-game opponent offensive rating (adjusted for rest and travel), home/away indicator, game total line as proxy for expected pace, binary indicator for games with large score differential (>15) midway through the third to proxy for garbage-time effects, and an interaction term for opponent offensive rating × halftime differential to account for whether strong offenses adjust differently.",
    "falsification": "1) Null hypothesis that the previous season's measure does not predict the next season's measure after controlling for team overall defensive rating; if it does not, the trait is not independently stable. 2) Test that the defensive H2-H1 trait does not predict first-half opponent scoring in the subsequent season; a positive coefficient would indicate the measure is capturing general defensive ability rather than halftime-specific adjustment. 3) Permutation test shuffling team labels across seasons to generate an empirical null distribution of the correlation coefficient.",
    "multiplicity": "If multiple operationalizations (e.g., raw differential, p.p.p-adjusted, with/without garbage time) are tested, apply Benjamini-Hochberg correction across the primary family of year-to-year correlation tests, pre-registering a single primary specification.",
    "decision_rule": "Declare the trait reliable if the pre-registered year-to-year Pearson correlation is significantly positive (one-sided p < 0.025) AND the lower bound of a 95% bootstrap confidence interval exceeds 0.20. A Spearman correlation is reported as a robustness check but does not override the primary decision.",
    "data_version": "NBA stats API play-by-play, boxscore, and substitution data as of 2026-10-06, plus derived play-type possession records. Per-game files are frozen at the end of each completed season; 2025-26 regular season data is included only if the season is complete; otherwise it is used for supplementary power simulation only."
  }
}

